export type RegistrationStatus = 'draft' | 'pending_payment' | 'registered' | 'pending_review' | 'approved' | 'accepted_pending_payment' | 'confirmed' | 'cancelled' | 'checked_in';
export type EventRegistration = {
    id: string;
    eventId: string;
    registrationTypeId: string;
    programId: string | null;
    participantProfileId: string;
    userId: string | null;
    status: RegistrationStatus;
    amountCents: number;
    currency: string;
    email?: string;
    firstName?: string;
    lastName?: string;
    phone?: string | null;
    institution?: string | null;
    country?: string | null;
    knowledgeAreaId?: string | null;
    knowledgeLineId?: string | null;
    professionalExperience?: Array<Record<string, unknown>>;
    teamMembers?: Array<{
        id: string;
        role: 'advisor' | 'team_member';
        fullName: string;
        email: string;
        sortOrder: number;
    }>;
    participationMode?: 'attendee' | 'presenter';
    formId?: string | null;
    formAnswers?: Record<string, unknown>;
    speakerId?: string | null;
    eventName?: string;
    eventSlug?: string;
    eventLogoFileId?: string | null;
    createdAt: Date;
    updatedAt: Date;
};
